#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct BufferEnded;

pub trait ByteSource {
    fn read_into(&mut self, dst: &mut [u8]) -> Result<usize, BufferEnded>;
    fn read_byte(&mut self) -> Result<u8, BufferEnded>;

    fn read_until<F>(&mut self, out: &mut Vec<u8>, mut stop: F) -> Result<usize, BufferEnded>
    where
        Self: Sized,
        F: FnMut(u8, u8) -> bool,
    {
        let mut count = 0;
        let mut previous = None;
        loop {
            let current = self.read_byte()?;
            out.push(current);
            count += 1;
            if let Some(prev) = previous {
                if stop(current, prev) {
                    return Ok(count);
                }
            }
            previous = Some(current);
        }
    }
}

pub struct SliceSource<'a> {
    data: &'a [u8],
    offset: usize,
}

impl<'a> SliceSource<'a> {
    pub fn new(data: &'a [u8]) -> Self {
        Self { data, offset: 0 }
    }
}

impl ByteSource for SliceSource<'_> {
    fn read_into(&mut self, dst: &mut [u8]) -> Result<usize, BufferEnded> {
        if dst.is_empty() {
            return Ok(0);
        }
        if self.offset == self.data.len() {
            return Err(BufferEnded);
        }
        let count = dst.len().min(self.data.len() - self.offset);
        dst[..count].copy_from_slice(&self.data[self.offset..self.offset + count]);
        self.offset += count;
        Ok(count)
    }

    fn read_byte(&mut self) -> Result<u8, BufferEnded> {
        let byte = self.data.get(self.offset).copied().ok_or(BufferEnded)?;
        self.offset += 1;
        Ok(byte)
    }
}

