#[path = "solution.rs"]
mod solution;

use solution::{BufferEnded, ByteSource, SliceSource};

#[test]
fn read_into_respects_capacity_tail_and_exhaustion() {
    let input = [1, 2, 3, 4, 5];
    let original = input;
    let mut source = SliceSource::new(&input);
    let mut dst = [99; 8];

    assert_eq!(source.read_into(&mut dst[..3]), Ok(3));
    assert_eq!(&dst, &[1, 2, 3, 99, 99, 99, 99, 99]);
    assert_eq!(source.read_into(&mut dst), Ok(2));
    assert_eq!(&dst, &[4, 5, 3, 99, 99, 99, 99, 99]);
    assert_eq!(source.read_into(&mut dst[..1]), Err(BufferEnded));
    assert_eq!(source.read_into(&mut []), Ok(0));
    assert_eq!(input, original);
}

#[test]
fn read_byte_advances_and_reports_end() {
    let mut source = SliceSource::new(&[0, 255]);
    assert_eq!(source.read_byte(), Ok(0));
    assert_eq!(source.read_byte(), Ok(255));
    assert_eq!(source.read_byte(), Err(BufferEnded));
}

#[test]
fn read_until_matches_pairs_from_this_call_only() {
    let mut source = SliceSource::new(b"ab--tail");
    let mut out = vec![b'z'];
    let mut examined = Vec::new();

    let appended = source
        .read_until(&mut out, |previous, current| {
            examined.push((previous, current));
            previous == b'-' && current == b'-'
        })
        .unwrap();

    assert_eq!(appended, 4);
    assert_eq!(out, b"zab--");
    assert_eq!(examined, vec![(b'a', b'b'), (b'b', b'-'), (b'-', b'-')]);
    assert_eq!(source.read_byte(), Ok(b't'));
}

#[test]
fn read_until_preserves_appended_bytes_when_exhausted() {
    let mut source = SliceSource::new(b"abc");
    let mut out = vec![b'x'];
    let result = source.read_until(&mut out, |previous, current| {
        previous == b'x' && current == b'a'
    });

    assert_eq!(result, Err(BufferEnded));
    assert_eq!(out, b"xabc");
}

#[test]
fn read_until_empty_and_single_byte_sources_end_cleanly() {
    let mut empty = SliceSource::new(b"");
    let mut empty_out = Vec::new();
    assert_eq!(empty.read_until(&mut empty_out, |_, _| true), Err(BufferEnded));
    assert!(empty_out.is_empty());

    let mut single = SliceSource::new(b"q");
    let mut single_out = Vec::new();
    let mut calls = 0;
    assert_eq!(
        single.read_until(&mut single_out, |_, _| {
            calls += 1;
            true
        }),
        Err(BufferEnded)
    );
    assert_eq!(single_out, b"q");
    assert_eq!(calls, 0);
}

